import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation - basic format check
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column validation - allow alphanumeric and underscore
        if (sortCol != null && !sortCol.matches("^[a-zA-Z_]{1,30}$")) {
            sortCol = "created_at";
        }

        // Build query - sort is validated above, but filter is user-controlled
        String tableName = getTableForReport(reportType);
        StringBuilder query = new StringBuilder();
        query.append("SELECT * FROM ").append(tableName);
        query.append(" WHERE created_at BETWEEN '").append(startDate);
        query.append("' AND '").append(endDate).append("'");

        // Custom filter - intended for power users, documented as "field:value" format
        if (customFilter != null && !customFilter.isEmpty()) {
            // Basic sanitization: remove comments and semicolons
            String sanitized = customFilter.replaceAll("--", "").replaceAll(";", "");
            // Additional check: reject if contains obvious SQL keywords followed by space
            if (sanitized.toLowerCase().matches(".*(union\\s+select|drop\\s+table|insert\\s+into).*")) {
                log.warning("Blocked suspicious filter: " + customFilter);
                resp.sendError(400, "Invalid filter");
                return;
            }
            query.append(" AND ").append(sanitized);
        }

        if (sortCol != null) {
            query.append(" ORDER BY ").append(sortCol);
        }
        query.append(" LIMIT 1000");

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("users") || type.equals("audit"));
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private String getTableForReport(String type) {
        switch (type) {
            case "sales": return "report_sales";
            case "inventory": return "report_inventory";
            case "users": return "report_users";
            case "audit": return "report_audit_log";
            default: return "report_sales";
        }
    }
}
